import { useEffect, useState } from 'react';
import axios from '../../api/axiosInstance';
import { useNavigate } from 'react-router-dom';

const Employees = () => {
    const [employees, setEmployees] = useState([]);
    const [search, setSearch] = useState('');
    const navigate = useNavigate();

    const fetchEmployees = async () => {
        const res = await axios.get('/employees');
        setEmployees(res.data);
    };

    useEffect(() => {
        fetchEmployees();
    }, []);

    const handleDelete = async (id) => {
        if (window.confirm('Xóa nhân sự này?')) {
            await axios.delete(`/employees/${id}`);
            fetchEmployees();
        }
    };

    const handleEdit = (employee) => {
        navigate('/admin/employees/add', { state: { editData: employee } });
    };

    return (
        <div>
            <h2>👥 Danh sách Nhân sự</h2>

            <input
                type="text"
                placeholder="Tìm kiếm..."
                onChange={(e) => setSearch(e.target.value)}
                style={{ marginBottom: '10px', padding: '8px', width: '300px' }}
            />

            <table border="1" cellPadding="10" width="100%">
                <thead>
                    <tr>
                        <th>Ảnh</th>
                        <th>Họ tên</th>
                        <th>Email</th>
                        <th>Điện thoại</th>
                        <th>Vị trí</th>
                        <th>Bộ phận</th>
                        <th>Lương</th>
                        <th>Bắt đầu</th>
                        <th>Hành động</th>
                    </tr>
                </thead>
                <tbody>
                    {employees.filter(e => e.name.toLowerCase().includes(search.toLowerCase())).map(emp => (
                        <tr key={emp._id}>
                            <td><img src={emp.avatar} alt="avatar" width="50" /></td>
                            <td>{emp.name}</td>
                            <td>{emp.email}</td>
                            <td>{emp.phone}</td>
                            <td>{emp.position}</td>
                            <td>{emp.department}</td>
                            <td>{emp.salary?.toLocaleString()}đ</td>
                            <td>{emp.startDate?.slice(0, 10)}</td>
                            <td>
                                <button onClick={() => handleEdit(emp)}>✏️</button>
                                <button onClick={() => handleDelete(emp._id)}>🗑️</button>
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>

            <button onClick={() => navigate('/admin/employees/add')} style={{ marginTop: 20 }}>➕ Thêm Nhân sự</button>
        </div>
    );
};

export default Employees;
